WHERE M.ROLE = 'ADM' AND M.UNIV_ID IS NOT NULL
AND ( LOWER(U.UNIV_NAME) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(M.MEMBER_NAME) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(M.LOGIN_ID) LIKE '%' || LOWER(#{keyword}) || '%' )
AND M.STATUS = #{status}

mapper.update:
UPDATE MEMBER
SET STATUS = #{status}
WHERE MEMBER_ID = #{memberId}
  AND ROLE = 'ADM'
  AND UNIV_ID IS NOT NULL

