mapper.sql:
WHERE M.ROLE IN ('GUEST', 'STU', 'PROF', 'ALU')

    AND (
        LOWER(M.MEMBER_NAME) LIKE '%' || LOWER(#{keyword}) || '%'
        OR LOWER(M.LOGIN_ID) LIKE '%' || LOWER(#{keyword}) || '%'
        OR LOWER(U.UNIV_NAME) LIKE '%' || LOWER(#{keyword}) || '%'
        OR LOWER(D.DEPT_NAME) LIKE '%' || LOWER(#{keyword}) || '%'
    )


    AND M.UNIV_ID = #{univId}


    AND M.ROLE = #{role}


    AND M.STATUS = #{status}

mapper.select:
SELECT
    (SELECT COUNT(*) FROM POST P WHERE P.MEMBER_ID = #{memberId}) AS postCount,
    (SELECT COUNT(*) FROM POST_COMMENT C WHERE C.MEMBER_ID = #{memberId}) AS commentCount,
    (
        SELECT COUNT(*)
        FROM LMS_PROFILE LP
        LEFT JOIN LECTURE_STUDENT_ENROLLMENT E ON E.LMS_PRF_ID = LP.LMS_PRF_ID
        LEFT JOIN LECTURE L ON L.LMS_PRF_ID = LP.LMS_PRF_ID
        WHERE LP.MEMBER_ID = #{memberId}
          AND (E.LEC_ID IS NOT NULL OR L.LEC_ID IS NOT NULL)
    ) AS courseCount,
    (
        SELECT COUNT(*)
        FROM LMS_PROFILE LP
        JOIN LECTURE_ASSIGNMENT_SUBMISSION S ON S.LMS_PRF_ID = LP.LMS_PRF_ID
        WHERE LP.MEMBER_ID = #{memberId}
    ) AS submissionCount,
    (
        SELECT COUNT(*) FROM READING_SEAT_RESERVATIONS R WHERE R.MEMBER_ID = #{memberId}
    ) + (
        SELECT COUNT(*) FROM MEETING_ROOM_RESERVATIONS R WHERE R.MEMBER_ID = #{memberId}
    ) AS reservationCount,
    (
        SELECT COUNT(*) FROM RESERVATION_PENALTIES P WHERE P.MEMBER_ID = #{memberId}
    ) AS noShowCount,
    (
        SELECT COUNT(DISTINCT IP.INQUIRY_ROOM_ID)
        FROM INQUIRY_PARTICIPANT IP
        WHERE IP.MEMBER_ID = #{memberId}
    ) AS inquiryCount
FROM DUAL

SELECT COUNT(*)
